381:   function drawAwning(ctx, g, height, colorA, colorB, y) {
382:     const baseY = y == null ? height - 13 : y;
383:     const segments = 6;
384:     for (let i = 0; i < segments; i++) {
385:       const t0 = i / segments, t1 = (i + 1) / segments;
386:       const a0 = { x: lerp(g.L.x, g.B.x, t0), y: lerp(g.L.y, g.B.y, t0) - baseY };
387:       const a1 = { x: lerp(g.L.x, g.B.x, t1), y: lerp(g.L.y, g.B.y, t1) - baseY };
388:       const b0 = { x: a0.x + 2, y: a0.y + 4 }, b1 = { x: a1.x + 2, y: a1.y + 4 };
389:       poly(ctx, [a0, a1, b1, b0], i % 2 ? colorB : colorA);
