434:       case 'factory': return drawFactory(ctx, b, def, time);
435:       case 'powerplant': return drawPowerPlant(ctx, b, time);
436:       case 'watertower': return drawWaterTower(ctx, b, time);
437:       case 'solar': return drawSolar(ctx, b, time);
438:       case 'police': return drawPolice(ctx, b, time);
439:       case 'fire': return drawFire(ctx, b, time);
440:       case 'school': return drawSchool(ctx, b, time);
441:       case 'hospital': return drawHospital(ctx, b, time);
442:       case 'smallpark': return drawSmallPark(ctx, b, time);
443:       case 'park': return drawPark(ctx, b, time);
444:       case 'plaza': return drawPlaza(ctx, b, time);
445:       case 'fountain': return drawFountain(ctx, b, time);
446:       case 'ferris': return drawFerris(ctx, b, time);
447:       case 'stadium': return drawStadium(ctx, b, time);
448:       case 'monument': return drawMonument(ctx, b, time);
449:       case 'tree': return drawTree(ctx, b, def, time);
