522:   function drawCar(ctx, car, time) {
523:     const p = iso(car.x + .5, car.y + .5);
524:     const dir = car.dir || 'x';
525:     const dxs = dir === 'x' ? 1 : dir === '-x' ? -1 : 0;
526:     const dys = dir === 'y' ? 1 : dir === '-y' ? -1 : 0;
527:     const ang = Math.atan2((dxs + dys) * IY, (dxs - dys) * IX);
528:     ctx.save();
529:     ctx.translate(p.x, p.y);
530:     ctx.fillStyle = 'rgba(20,45,30,.22)';
531:     ctx.beginPath(); ctx.ellipse(0, 1, 9, 4, ang, 0, 7); ctx.fill();
532:     ctx.rotate(ang + Math.PI);
533:     ctx.fillStyle = car.color || '#e6563d';
534:     roundRect(ctx, -7, -4, 14, 8, 3); ctx.fill();
535:     ctx.fillStyle = light(car.color || '#e6563d', .18);
536:     roundRect(ctx, -5, -3, 6, 6, 2); ctx.fill();
537:     ctx.fillStyle = 'rgba(30,45,55,.55)';
538:     roundRect(ctx, 1, -3, 4, 6, 1.5); ctx.fill();
539:     ctx.fillStyle = NIGHT > .28 ? '#ffe9a0' : '#f7f2df';
540:     ctx.fillRect(-8, -3, 1.6, 2); ctx.fillRect(-8, 1, 1.6, 2);
541:     if (NIGHT > .28) {
542:       ctx.globalAlpha = .25; ctx.fillStyle = '#ffe9a0';
543:       ctx.beginPath(); ctx.moveTo(-8, -2); ctx.lineTo(-20, -7); ctx.lineTo(-20, 4); ctx.closePath(); ctx.fill();
544:       ctx.globalAlpha = 1;
545:     }
546:     ctx.restore();
547:   }
