561:       ellipse(ctx, c.x, c.y, def.radius * 32, def.radius * 16, 'rgba(80,220,130,.055)', valid ? 'rgba(46,194,126,.5)' : 'rgba(255,90,60,.4)', 1.4);
562:       ctx.setLineDash([]);
