577:   // ---------- shared art helpers ----------
578:   function flatRoof(g, height, color, lipColor) {
579:     const T = { x: g.T.x, y: g.T.y - height }, R = { x: g.R.x, y: g.R.y - height }, B = { x: g.B.x, y: g.B.y - height }, L = { x: g.L.x, y: g.L.y - height };
580:     poly(ctx, [L, B, B, L], null);
581:     poly(ctx, [T, R, B, L].map(p => ({ x: lerp(p.x, (T.x + B.x) / 2, .08), y: lerp(p.y, (T.y + B.y) / 2, .08) })), color || '#d9d1c1');
582:     return { T, R, B, L };
583:   }
584:   function roofLip(ctx, g, height, color) {
585:     const T = { x: g.T.x, y: g.T.y - height }, R = { x: g.R.x, y: g.R.y - height }, B = { x: g.B.x, y: g.B.y - height }, L = { x: g.L.x, y: g.L.y - height };
586:     const cx = (T.x + B.x) / 2, cy = (T.y + B.y) / 2;
587:     const inset = p => ({ x: lerp(p.x, cx, .07), y: lerp(p.y, cy, .07) });
588:     const iT = inset(T), iR = inset(R), iB = inset(B), iL = inset(L);
589:     poly(ctx, [T, R, iR, iT], color); poly(ctx, [R, B, iB, iR], shade(color, .82));
590:     poly(ctx, [B, L, iL, iB], shade(color, .75)); poly(ctx, [L, T, iT, iL], shade(color, .92));
591:   }
592:   function cylinder(ctx, cx, baseY, rx, h, color) {
593:     const topY = baseY - h;
594:     const grd = ctx.createLinearGradient(cx - rx, 0, cx + rx, 0);
595:     grd.addColorStop(0, shade(color, .78));
596:     grd.addColorStop(.45, light(color, .12));
597:     grd.addColorStop(1, shade(color, .66));
598:     ctx.fillStyle = grd;
599:     ctx.beginPath(); ctx.moveTo(cx - rx, topY); ctx.lineTo(cx - rx, baseY); ctx.ellipse(cx, baseY, rx, rx * .42, 0, Math.PI, 0, true); ctx.lineTo(cx + rx, topY); ctx.closePath(); ctx.fill();
600:     ellipse(ctx, cx, topY, rx, rx * .42, light(color, .17), shade(color, .58), .7);
601:   }
602:   function smoke(ctx, cx, cy, time, scale) {
603:     const sc = scale || 1;
604:     for (let i = 0; i < 4; i++) {
605:       const t = (time * .19 + i * .25) % 1;
606:       const r = (4 + t * 12) * sc;
607:       ctx.globalAlpha = (1 - t) * .3;
608:       ctx.fillStyle = i % 2 ? '#e9f0ef' : '#d8e0df';
609:       ctx.beginPath(); ctx.arc(cx + Math.sin(time * .5 + i * 2.1) * 5 * sc, cy - t * 46 * sc, r, 0, 7); ctx.fill();
610:     }
611:     ctx.globalAlpha = 1;
612:   }
613:   function flag(ctx, x, y, h, time) {
614:     line(ctx, { x, y }, { x, y: y - h }, '#8b8f8b', 1.6);
615:     const wave = Math.sin(time * 2.4 + x * .1) * 1.8;
616:     poly(ctx, [{ x: x + 1, y: y - h }, { x: x + 1 + 11, y: y - h + 1 + wave }, { x: x + 1 + 11, y: y - h + 5 + wave }, { x: x + 1, y: y - h + 4 }], '#e0453a');
617:     poly(ctx, [{ x: x + 1, y: y - h + 4 }, { x: x + 1 + 11, y: y - h + 5 + wave }, { x: x + 1 + 11, y: y - h + 8 + wave }, { x: x + 1, y: y - h + 7 }], '#f7f4ec');
618:   }
619:   function basePad(ctx, b, color1, color2) {
620:     const p = diamondPoints(b.x, b.y, b.w, b.h, .015);
621:     poly(ctx, p, color1 || '#d9d0ba');
622:     const p2 = diamondPoints(b.x, b.y, b.w, b.h, .08);
623:     poly(ctx, p2, color2 || light(color1 || '#d9d0ba', .12));
624:   }
