273:         if (t.b.defId === 'tree' || t.b.defId === 'rock') wild = true;
274:         else return { ok: false, msg: 'Petak sudah terisi.' };
275:       }
276:     }
277:     if (wild) return { ok: false, msg: 'Bersihkan pohon/batu dengan alat bongkar dulu.' };
278:     if (def.kind !== 'road' && def.kind !== 'decor') {
279:       let ok = false;
280:       const test = { x, y, w: def.w, h: def.h };
281:       ok = roadAccess(test);
282:       if (!ok) return { ok: false, msg: 'Butuh akses jalan di sebelahnya.' };
283:     }
284:     if (!opts.free && state.money < def.cost) return { ok: false, msg: 'Kas kota tidak cukup.' };
285:     return { ok: true };
