345:   // ---------- cars ----------
346:   function allRoads() {
347:     const list = [];
348:     for (let y = 0; y < state.gridSize; y++) for (let x = 0; x < state.gridSize; x++) if (state.grid[idx(x, y)].road) list.push({ x, y });
349:     return list;
350:   }
351:   const CAR_COLORS = ['#e6563d', '#3b8fd4', '#f2c94c', '#4fae62', '#c14b7c', '#f28b3c', '#6b7c8a', '#f7f4ec'];
352:   function newCar(tx, ty) {
353:     const choices = [];
354:     for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
355:       const nx = tx + dx, ny = ty + dy;
356:       if (inBounds(nx, ny) && state.grid[idx(nx, ny)].road) choices.push({ x: nx, y: ny, dx, dy });
357:     }
358:     if (!choices.length) return null;
359:     const c = choices[Math.floor(Math.random() * choices.length)];
360:     return {
361:       x: tx + .5, y: ty + .5, fromX: tx + .5, fromY: ty + .5, toX: c.x + .5, toY: c.y + .5,
362:       t: 0, speed: .45 + Math.random() * .35, color: CAR_COLORS[Math.floor(Math.random() * CAR_COLORS.length)],
363:       dir: c.dx > 0 ? 'x' : c.dx < 0 ? '-x' : c.dy > 0 ? 'y' : '-y', alive: true
364:     };
365:   }
366:   function spawnCars(initial) {
367:     const roads = allRoads();
368:     if (!roads.length) return;
369:     const cap = Math.min(16, Math.floor(roads.length / 2.4));
370:     while (state.cars.length < cap) {
371:       const r = roads[Math.floor(Math.random() * roads.length)];
372:       const c = newCar(r.x, r.y);
373:       if (!c) break;
374:       c.t = initial ? Math.random() : 0;
375:       c.x = lerp(c.fromX, c.toX, c.t); c.y = lerp(c.fromY, c.toY, c.t);
376:       state.cars.push(c);
377:       if (state.cars.length > 40) break;
378:     }
379:   }
380:   function ensureCars() { spawnCars(); }
381:   function updateCars(dt) {
382:     if (!state || !state.cars) return;
383:     for (const c of state.cars) {
384:       if (!c.alive) continue;
385:       c.t += dt * c.speed;
386:       if (c.t >= 1) {
387:         const tx = Math.round(c.toX - .5), ty = Math.round(c.toY - .5);
388:         c.fromX = c.toX; c.fromY = c.toY;
389:         const choices = [];
390:         for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
391:           const nx = tx + dx, ny = ty + dy;
392:           if (inBounds(nx, ny) && state.grid[idx(nx, ny)].road) {
393:             if (dx === -c.dx && dy === -c.dy && choices.length) continue;
394:             choices.push({ x: nx, y: ny, dx, dy });
395:           }
396:         }
397:         if (!choices.length) { c.alive = false; continue; }
398:         const pick = choices[Math.floor(Math.random() * choices.length)];
399:         c.toX = pick.x + .5; c.toY = pick.y + .5;
400:         c.dir = pick.dx > 0 ? 'x' : pick.dx < 0 ? '-x' : pick.dy > 0 ? 'y' : '-y';
401:         c.t = 0;
402:       }
403:       c.x = lerp(c.fromX, c.toX, c.t);
404:       c.y = lerp(c.fromY, c.toY, c.t);
405:     }
406:     state.cars = state.cars.filter(c => c.alive);
407:     const roads = allRoads();
408:     if (state.cars.length < Math.min(14, Math.floor(roads.length / 2.4)) && Math.random() < .02) {
409:       const r = roads[Math.floor(Math.random() * roads.length)];
410:       if (r) { const c = newCar(r.x, r.y); if (c) state.cars.push(c); }
411:     }
412:   }
