841:   function updateMinimap() {
842:     const cv = $('#minimap'); if (!cv || !state) return;
843:     const c = cv.getContext('2d');
844:     const w = cv.width, h = cv.height;
845:     c.clearRect(0, 0, w, h);
846:     c.fillStyle = '#8ccfe0'; c.fillRect(0, 0, w, h);
847:     const size = state.gridSize;
848:     const padX = (w - (Math.min(w, h) - 16)) / 2 + 8;
849:     const padY = (h - (Math.min(w, h) - 16)) / 2 + 8;
850:     const cell = (Math.min(w, h) - 16) / size;
851:     for (let y = 0; y < size; y++) for (let x = 0; x < size; x++) {
852:       const t = state.grid[idx(x, y)];
853:       let col = t.terrain === 'water' ? '#3b93b3' : t.terrain === 'sand' ? '#e6d29c' : '#87c568';
854:       if (t.road) col = '#59626a';
855:       if (t.b) {
856:         const d = defOf(t.b);
857:         if (d.kind === 'zone-r') col = '#3aa96b';
858:         else if (d.kind === 'zone-c') col = '#3b8fd4';
859:         else if (d.kind === 'zone-i') col = '#d9a03c';
860:         else if (d.cat === 'service') col = '#e05a8b';
861:         else if (d.cat === 'fun') col = '#f0a33e';
862:         else if (d.kind === 'decor') col = t.b.defId === 'tree' ? '#4f9b54' : '#7bc46a';
863:         else col = '#6f8f89';
864:       }
865:       c.fillStyle = col;
866:       c.fillRect(padX + x * cell, padY + y * cell, Math.ceil(cell), Math.ceil(cell));
867:     }
868:     // camera marker (approx)
869:     const gx = (cam.x / 32 + cam.y / 16) / 2;
870:     const gy = (cam.y / 16 - cam.x / 32) / 2;
871:     c.strokeStyle = 'rgba(255,255,255,.95)'; c.lineWidth = 2;
872:     c.strokeRect(padX + gx * cell - 8, padY + gy * cell - 8, 16, 16);
873:     c.fillStyle = 'rgba(255,255,255,.9)';
874:     c.beginPath(); c.arc(padX + gx * cell, padY + gy * cell, 2.5, 0, 7); c.fill();
875:     // frame
876:     c.strokeStyle = 'rgba(9,57,62,.15)'; c.lineWidth = 1; c.strokeRect(0, 0, w, h);
877:   }
